def a_compose_lesson(rng, key, idx):
    text, good, wrongs = LESSON_PHRASES[idx % len(LESSON_PHRASES)]
    return g.mc(rng, key, "A.applications", "Съставя израз по текстово условие", "INTERMEDIATE", "REASONING",
                f"Кой израз означава „{text}“?", good, wrongs,
                ["Раздели изречението на части: кое е последното действие?", "Последното действие определя вида на израза.", f"Отговорът започва така: {good[:2]}…"],
                f"„{text}“ се записва като {good}.", "A")


_compose_i = [0]


def compose(rng, key):
    _compose_i[0] += 1
    return a_compose_lesson(rng, key, _compose_i[0] - 1)


# ------------------------------------------------------------------ templates for A1, C1, C9, D2
P, F, nz, lin, val = g.P, g.F, g.nz, g.lin, g.val
LETTER_PAIRS = [("a", "b"), ("m", "n"), ("x", "y"), ("p", "q")]


def a1_numeric_mc(rng, key):
    a, b, c, d = rng.randint(2, 6), rng.randint(1, 9), rng.randint(1, 9), rng.randint(1, 9)
    u = rng.choice("xyamn")
    good = f"{a}·({b} + {c}) − {d}"
    why = "В израза има буква ({}) — това е израз с променливи, а не числов израз."
    wrongs = [(f"{a}{u} + {b}", "REASONING", why.format(u)), (f"({b} + {u})·{c}", "REASONING", why.format(u)),
              (f"{d}{u}² − {c}", "REASONING", why.format(u))]
    return g.mc(rng, key, "A.expressions", "Разпознава числов израз и израз с променливи", "FOUNDATIONAL", "REASONING",
                "Кой от изразите е числов израз (без променливи)?", good, wrongs,
                ["Числовият израз съдържа само числа, знаци за действия и скоби.", "Потърси израза без букви.", "Изразите с x, a, m и т.н. са с променливи."],
                f"{good} съдържа само числа и действия, затова е числов израз. Стойността му е {a * (b + c) - d}.", "A", secs=30)


def a1_variables_mc(rng, key):
    u, v = rng.choice(LETTER_PAIRS)
    k, m, c = rng.randint(2, 9), rng.randint(2, 9), rng.randint(1, 9)
    if len({k, m, c}) < 3:
        raise ValueError
    expr = f"{k}{u}² − {m}{u}{v} + {c}"
    wrongs = [(f"{k}, {m} и {c}", "REASONING", "Това са числата в израза — те са константи, а не променливи."),
              (f"само {u}", "REASONING", f"{v} също е буква, която може да приема различни стойности — и тя е променлива."),
              (f"{u}, {v} и {c}", "REASONING", f"{c} е число — константа, а не променлива.")]
    return g.mc(rng, key, "A.expressions", "Разпознава променливите в израз", "FOUNDATIONAL", "REASONING",
                f"Кои са променливите в израза {expr}?", f"{u} и {v}", wrongs,
                ["Променливите са буквите в израза.", "Числата са константи.", f"В израза има две различни букви."],
                f"Променливите са буквите {u} и {v}; числата {k}, {m} и {c} са константи.", "A", secs=30)


MONO_POOL = [dict(x=3), dict(x=2, y=1), dict(x=2), dict(x=1, y=1), dict(y=2), dict(x=1), dict(y=1), dict()]


def rand_poly(rng, n):
    mons = rng.sample(MONO_POOL, n)
    return sum((P.mono(nz(rng, -9, 9), **m) for m in mons), P())


def c1_terms_count(rng, key):
    n = rng.randint(3, 5)
    p = rand_poly(rng, n)
    return g.q(key, "C.definition", "Разпознава членовете на многочлен", "NUMERIC", "FOUNDATIONAL", 30, 1, "REASONING",
               f"Колко члена има многочленът {p.fmt()}?", "C", answer=str(n),
               distractors=[{"match": str(n - 1), "misconception": "REASONING", "explanation": "Броим всички едночлени, включително свободния член (числото без буква)."},
                            {"match": str(n + 1), "misconception": "REASONING", "explanation": "Знаците + и − не са членове — те стоят пред членовете."}],
               hints=["Членовете са едночлените, разделени със знаците + и −.", "Свободният член също се брои.", "Преброй едночлените един по един."],
               solution=f"Членовете на {p.fmt()} са: " + ", ".join(P({m: c}).fmt() for m, c in p.ordered()) + f". Те са {n}.")


def c1_coef_mc(rng, key):
    a, b, c = nz(rng, -9, 9), nz(rng, -9, 9), nz(rng, -9, 9)
    p = P.mono(a, x=2) + P.mono(b, x=1) + P.const(c)
    wrongs = [(val(-b), "SIGN", "Знакът пред члена е част от коефициента."),
              (val(a), "REASONING", "Това е коефициентът пред x², а търсим коефициента пред x."),
              (val(c), "REASONING", "Това е свободният член — той няма буквена част.")]
    return g.mc(rng, key, "C.definition", "Определя коефициентите на многочлен", "FOUNDATIONAL", "SIGN",
                f"Какъв е коефициентът пред x в многочлена {p.fmt()}?", val(b), wrongs,
                ["Намери члена, който съдържа x (без степен).", "Коефициентът е числото пред буквената част.", "Не забравяй знака пред члена."],
                f"Членът с x е {P.mono(b, x=1).fmt()}, затова коефициентът е {val(b)}.", "C", secs=30, expect=val(b, False))


def c1_is_poly_mc(rng, key):
    p = P.mono(nz(rng, 2, 7), x=2) + P.mono(nz(rng, -7, 7), x=1) + P.const(nz(rng, -9, 9))
    k, m = rng.randint(2, 9), rng.randint(1, 9)
    why = "Тук има деление на израз с променлива — това е дробен израз, а не многочлен."
    wrongs = [(f"{k}/x + {m}", "REASONING", why), (f"x + {m}/(x − {k})", "REASONING", why), (f"{k}x² − 1/y", "REASONING", why)]
    return g.mc(rng, key, "C.definition", "Разпознава многочлен", "FOUNDATIONAL", "REASONING",
                "Кой от изразите е многочлен?", p.fmt(), wrongs,
                ["Многочленът е сбор от едночлени.", "В едночлена няма деление на променлива.", "Потърси израза без променлива в знаменател."],
                f"{p.fmt()} е сбор от едночлените, затова е многочлен. В другите изрази се дели на израз с променлива.", "C", secs=40)


def c1_free_term(rng, key):
    p = rand_poly(rng, 3) + P.const(nz(rng, -9, 9))
    if len(p.t) < 3:
        raise ValueError
    c = p.t.get((), F(0))
    if c == 0:
        raise ValueError
    return g.q(key, "C.definition", "Намира свободния член на многочлен", "NUMERIC", "FOUNDATIONAL", 30, 1, "SIGN",
               f"Кой е свободният член на многочлена {p.fmt()}? Запиши числото.", "C", answer=val(c, False),
               distractors=[{"match": val(-c, False), "misconception": "SIGN", "explanation": "Знакът пред свободния член е част от него."}],
               hints=["Свободният член е членът без буква.", "Обикновено е последен в нормалния вид.", "Запиши го заедно със знака."],
               solution=f"Членът без променлива в {p.fmt()} е {val(c)}.")


def c9_product_mc(rng, key):
    b, s = rng.randint(1, 5), rng.choice([1, -1])
    x = P.mono(1, x=1)
    first = lin(1, s * b)
    second = P.mono(1, x=2) + P.mono(-s * b, x=1) + P.const(b * b)
    same = P.mono(1, x=2) + P.mono(s * b, x=1) + P.const(b * b)
    res = first * second
    wrongs = [((first ** 3).fmt(), "FORMULA_APPLICATION", f"Това е ({first.fmt()})³ — кубът на двучлена има четири члена, а произведението тук дава само два."),
              ((first * same).fmt(), "SIGN", "Това би се получило, ако средният член във втората скоба беше със същия знак. Във формулата той е с обратен знак и средните членове се унищожават."),
              ((x ** 3 - (res - x ** 3)).fmt(), "SIGN", "Знакът пред b³ е същият като в първата скоба.")]
    return g.mc(rng, key, "C.sum-cubes", "Прилага формулите a³ ± b³", "INTERMEDIATE", "FORMULA_APPLICATION",
                f"({first.fmt()})({second.fmt()}) е равно на:", res.fmt(), wrongs,
                ["Това е формулата за сбор или разлика на кубове.", "a³ + b³ = (a + b)(a² − ab + b²), a³ − b³ = (a − b)(a² + ab + b²).", f"Тук a = x, b = {b}."],
                f"({first.fmt()})({second.fmt()}) = {res.fmt()} — средните членове се унищожават.", "C", expect=res.fmt(False))


def c9_expand(rng, key):
    b, s = rng.randint(1, 6), rng.choice([1, -1])
    first = lin(1, s * b)
    second = P.mono(1, x=2) + P.mono(-s * b, x=1) + P.const(b * b)
    res = first * second
    return g.q(key, "C.sum-cubes", "Прилага формулите a³ ± b³", "EXPRESSION", "INTERMEDIATE", 90, 2, "FORMULA_APPLICATION",
               f"Умножи и запиши в нормален вид: ({first.fmt()})({second.fmt()})", "C", answer=res.fmt(False), form="NORMAL_FORM",
               distractors=[{"match": (first ** 3).fmt(False), "misconception": "FORMULA_APPLICATION", "explanation": "Това е кубът на двучлена, а не произведението от формулата."}],
               hints=["Разпознай формулата за сбор/разлика на кубове.", "Средните членове ще се унищожат.", f"Остават x³ и {val(s * b ** 3)}."],
               solution=f"По формулата: ({first.fmt()})({second.fmt()}) = x³ {'+' if s > 0 else '−'} {b}³ = {res.fmt()}.")


def c9_factor_mc(rng, key):
    b, s = rng.randint(1, 5), rng.choice([1, -1])
    target = P.mono(1, x=3) + P.const(s * b ** 3)
    first, other = lin(1, s * b), lin(1, -s * b)
    sq = lambda m: (P.mono(1, x=2) + P.mono(m * b, x=1) + P.const(b * b)).fmt()
    good = f"({first.fmt()})({sq(-s)})"
    wrongs = [(f"({first.fmt()})³", "FORMULA_APPLICATION", f"({first.fmt()})³ = {(first ** 3).fmt()} — има и средни членове, затова не е равно на {target.fmt()}."),
              (f"({first.fmt()})({sq(s)})", "SIGN", "Средният член в непълния квадрат е с обратния знак на този в първата скоба."),
              (f"({other.fmt()})({sq(s)})", "SIGN", f"Това е разлагането на {(P.mono(1, x=3) - P.const(s * b ** 3)).fmt()} — знаците са разменени.")]
    return g.mc(rng, key, "C.sum-cubes", "Разлага сбор и разлика на кубове", "ADVANCED", "FORMULA_APPLICATION",
                f"Разложи на множители: {target.fmt()}", good, wrongs,
                [f"Запиши {b ** 3} като куб: {b ** 3} = {b}³.", "Приложи формулата за сбор или разлика на кубове.", "Средният член в непълния квадрат е с обратен знак."],
                f"{target.fmt()} = x³ {'+' if s > 0 else '−'} {b}³ = {good}.", "C", expect=target.fmt(False))


def d2_which_wrong(rng, key):
    a = rng.randint(2, 6)
    items = [  # (wrong version, why it is wrong, correct version)
        (f"(x + {a})² = x² + {a * a}", f"липсва удвоеното произведение {2 * a}x", f"(x + {a})² = x² + {2 * a}x + {a * a}"),
        (f"−(x − {a}) = −x − {a}", f"минусът пред скобата сменя знака и на −{a}, така че се получава +{a}", f"−(x − {a}) = −x + {a}"),
        (f"{a}x + {a}x = {2 * a}x²", "при събиране буквената част не се променя", f"{a}x + {a}x = {2 * a}x"),
        (f"(x − {a})(x + {a}) = x² + {a * a}", f"разликата на квадрати е x² − {a * a}", f"(x − {a})(x + {a}) = x² − {a * a}"),
        (f"{a}x·{a}x = {2 * a}x²", f"коефициентите се умножават: {a}·{a} = {a * a}", f"{a}x·{a}x = {a * a}x²"),
    ]
    i = rng.randrange(len(items))
    others = [j for j in range(len(items)) if j != i]
    rng.shuffle(others)
    wrongs = [(items[j][2], "REASONING", "Това преобразувание е вярно — провери го с x = 2. Грешното е друго.") for j in others[:3]]
    bad, why, right = items[i]
    return g.mc(rng, key, "D.checking", "Открива и поправя типични грешки", "INTERMEDIATE", "REASONING",
                "Кое от преобразуванията е ГРЕШНО?", bad, wrongs,
                ["Провери всяко равенство, като заместиш x = 2 от двете страни.", "Където двете страни дават различни числа, има грешка.", "Внимавай за знаци, удвоено произведение и подобни членове."],
                f"Грешно е „{bad}“: {why}. Вярно е: {right}.", "D", secs=90)


