SUPPORT = ["FULL", "PARTIAL", "NONE"]


def build(existing_prompts):
    rng = random.Random(20261007)
    questions, lessons = [], []
    for L in LESSONS:
        seen = set()
        keys = {"pre": [], "guided": [], "check": []}

        def make(fns, role):
            for i, fn in enumerate(fns):
                made = None
                for _ in range(40):
                    key = f"L{L['key']}-{role[0].upper()}{i + 1}"
                    try:
                        qd = fn(rng, key)
                    except (ValueError, ZeroDivisionError):
                        continue
                    text = qd["draft"]["prompt"]["text"]
                    sig = text + "|" + "|".join(o["text"] for o in qd["draft"]["prompt"].get("options", []))
                    if sig in seen:
                        continue
                    seen.add(sig)
                    made = qd
                    break
                if not made:
                    raise RuntimeError(f"cannot build {L['key']} {role} {i}")
                questions.append(made)
                keys[role].append(made["key"])

        make(L["pre"], "pre")
        make(L["guided"], "guided")
        make(L["check"], "check")
        ctx_t, ctx = L["context"]
        def_t, defn = L["definition"]
        vis_t, vis_d, groups = L["visual"]
        content = {
            "context": {"title": ctx_t, "text": ctx},
            "objectives": L["objectives"],
            "prerequisiteCheck": {"intro": "Да проверим какво ще ти трябва.", "questionKeys": keys["pre"]},
            "explanation": L["explanation"],
            "definition": {"title": def_t, "text": defn},
            "visual": {"kind": "tiles", "title": vis_t, "description": vis_d,
                       "groups": [{"label": lab, "items": items, "colour": col} for lab, items, col in groups]},
            "workedExamples": [{"level": lv, "problem": prob, "steps": [{"expression": e, "why": w} for e, w in steps], "answer": ans}
                               for lv, prob, steps, ans in L["examples"]],
            "watchOut": [{"wrong": w, "right": r, "why": y} for w, r, y in L["watch"]],
            "guidedPractice": [{"questionKey": k, "support": SUPPORT[i], "coaching": c}
                               for i, (k, c) in enumerate(zip(keys["guided"], ["Следвай правилото от дефиницията стъпка по стъпка.", "Опитай сам(а); подсказките са тук, ако трябват.", "Сега изцяло сам(а)."]))],
            "check": {"intro": "Кратка проверка без оценка — само за теб.", "questionKeys": keys["check"]},
            "summary": L["summary"],
            "nextStep": {"lessonKey": L["next"][0], "text": L["next"][1]},
        }
        lessons.append({"lessonKey": L["key"], "content": content})
    return questions, lessons
